/* Types */
export type Action = "play" | 
/**  Epic and GOG: start an out-of-date game without updating it first (a GOG Play never updates). */
"playOutdated" | "install" | 
/**  Epic and GOG; Steam updates games itself. */
"update" | "uninstall" | 
/**  Epic and GOG verify and repair here; Steam validates in its own window. */
"verify" | 
/**  Epic and GOG move the folder to `dest`; Steam opens its storage manager. */
"move";

export type Card = {
	key: string,
	/**  The copy key Play and Install use (`entries::default_copy`). */
	chosen: string,
	/**  Every copy's key, for matching running state and install progress. */
	copyKeys: string[],
	title: string,
	stores: Store[],
	installed: boolean,
	/**  The chosen copy has an update to install. */
	update: boolean,
	/**  Summed over the copies; `None` when no store knows. */
	playtimeMinutes: number | null,
	/**  How long to beat ("normally") in shown hours, from the cache; `None` when unknown. */
	ttbHours: number | null,
	/**  Any copy is a favorite, hidden, or in the collection (ids). */
	favorite: boolean,
	hidden: boolean,
	collections: number[],
};

export type Collection = {
	id: number,
	name: string,
	/**  Games in it. */
	count: number,
};

/**  Why an Epic or GOG Play didn't launch yet: the question to ask first. */
export type Conflict = "localNewer" | "cloudNewer";

/**  One answer to the dialog's poll. Never carries the refresh token. */
export type ConnectStep = { step: "waiting" } | { step: "rotated"; svg: string } | { step: "scanned" } | { step: "connected"; account: string } | 
/**  The login was approved but couldn't be saved; the dialog stops here. */
{ step: "failed"; message: Msg };

export type CopyView = {
	key: string,
	provider: Store,
	installed: boolean,
	/**  An installed Epic or GOG copy has a newer version. */
	updateAvailable: boolean,
	/**  Size on disk of an installed copy. */
	sizeBytes: number | null,
	/**  Only for an installed copy (Steam knows a folder for games it hasn't installed yet). */
	installDir: string | null,
	/**  An installed Epic or GOG copy that keeps its saves in its store's cloud. */
	cloudSaves: boolean,
};

export type Cover = {
	src: string,
	/**  Average colour, `#rrggbb`, painted until the image has loaded. */
	color: string | null,
};

/**  The cover picked in the dialog: a SteamGridDB image or a local file. Copied into the data folder. */
export type CoverPick = ({ url: string }) & { file?: never } | ({ file: string }) & { url?: never };

/**  What the Edit dialog starts from. */
export type CustomGame = {
	name: string,
	exe: string,
	args: string,
};

export type Detail = {
	/**  The entry key. */
	key: string,
	title: string,
	stores: Store[],
	/**  Any copy. */
	installed: boolean,
	copies: CopyView[],
	/**  The copy key Play and Install use. */
	chosen: string,
	/**  Playtime tile minutes, 0 being never played; `None` hides the tile (an Epic copy with no known playtime). */
	playtimeMinutes: number | null,
	/**  The stores whose playtime is summed, only when more than one is. */
	playtimeStores: Store[],
	/**  Unix seconds; `None` when never played. */
	lastPlayed: number | null,
	/**  The store played on last, only for an entry with several copies. */
	lastPlayedStore: Store | null,
	/**  Store pages, then info sites when the Steam app id is known. */
	links: LinkKind[],
	/**  The Epic and GOG copies' DLC; a Steam copy's comes from `steam_dlc`. */
	dlc: Dlc[],
	/**  Any copy is a favorite, hidden, or in the collection (ids). */
	favorite: boolean,
	hidden: boolean,
	collections: number[],
};

export type DetailArt = {
	hero: string | null,
};

export type Dlc = {
	id: string,
	title: string,
	installed: boolean,
	/**  The Epic copy's key, for Install and Uninstall. */
	copy: string | null,
};

export type Featured = {
	key: string,
	/**  The copy key Play uses. */
	chosen: string,
	copyKeys: string[],
	title: string,
	hero: string | null,
};

/**
 *  What the game page shows. Missing facts are empty or `None` so the UI can hide them.
 *  Cached and returned with screenshot URLs; the `screenshots` command turns those into local files.
 */
export type GameInfo = {
	description: string,
	genres: string[],
	developer: string | null,
	publisher: string | null,
	released: string | null,
	screenshots: string[],
	/**  Whether the Steam store page lists DLC; `None` when unknown (other sources, older caches). */
	hasDlc?: boolean | null,
};

export type GridCover = {
	/**  The full image, passed back to `save_custom_game`. */
	url: string,
	/**  A local copy of the preview, ready for the asset protocol (the CSP allows no remote images). */
	thumb: string,
};

/**  An owned Epic game that isn't installed, for "Import an existing install". */
export type Importable = {
	key: string,
	title: string,
};

/**  The answer to a cloud save conflict. */
export type Keep = "cloud" | "local";

/**  A copy's own launch options, kept in `game_prefs` as JSON. `exe` is relative to the install folder. */
export type LaunchOptions = {
	/**  Extra game arguments as typed; split by `split_args`. */
	args?: string,
	offline?: boolean,
	skipVersionCheck?: boolean,
	exe?: string | null,
	/**  Linux: the Proton build this game runs with, by folder name; none follows Settings. */
	proton?: string | null,
};

export type Library = {
	/**  In order; grouped by the sort, group after group. */
	games: Card[],
	/**  The groups over `games`, in order; empty for Title without favorites. */
	groups: Section[],
	/**  Games in the library, hidden ones left out. */
	total: number,
	/**  Shown when nothing is listed: one line each. */
	status: Msg[],
	epic: StoreLogin | null,
	/**  Epic was set up here and broke (`attention`). */
	epicAttention: boolean,
	/**  Steam rejected the saved login: the settings button carries a dot too. */
	steamAttention: boolean,
	epicNotice: boolean,
	gog: StoreLogin | null,
	/**  The same for GOG. */
	gogAttention: boolean,
	amazon: StoreLogin | null,
	/**  The same for Amazon. */
	amazonAttention: boolean,
	/**  The stores the whole library has a game from, in toolbar order; games the owner added don't count. */
	stores: Store[],
};

export type LinkKind = "steamStore" | "epicStore" | "pcGamingWiki" | "steamDb" | "protonDb";

/**  One answer to the password login. Never carries the password, the code or the token. */
export type LoginStep = 
/**  Approve the login: in the Steam app, or (`email`) with the link Steam emailed. */
{ step: "approve"; email: boolean } | 
/**  Type the Steam Guard code sent by `kind`: "email" or "app". */
{ step: "code"; kind: string } | { step: "connected"; account: string } | { step: "failed"; message: Msg };

/**  `{ "code": "gameNotInLibrary", "params": { … } }`. A `Msg` param is rendered first and put in place. */
export type Msg = {
	code: string,
	params?: { [key in string]: Param },
};

export type Param = Msg | 
/**  Shown as is: a title, a path, a tool's own words, or text stored before message codes. */
string;

export type Poll = {
	/**  Key of the game running: Steam's, or the Epic or added game watched since its launch here. */
	running: string | null,
	/**
	 *  The running game is a Windows game on Linux whose first launch still sets up (umu fetching the Steam Linux
	 *  Runtime or making its prefix); it ends once the game's program runs.
	 */
	settingUp: boolean,
	progress: { [key in string]: Progress },
	/**  The library changed (a Steam download finished), so the UI should re-ask `library`. */
	changed: boolean,
	/**  The Epic download queue. */
	queue: QueueView,
};

export type PrefixSize = {
	key: string,
	bytes: number,
};

export type PrefixTool = "winecfg" | "winetricks";

export type PrefixView = {
	key: string,
	/**  The game's name; `None` when it is no longer in the library. */
	title: string | null,
};

/**
 *  Download progress as each store reports it: Steam in bytes, Legendary as a percentage with an ETA.
 *  The UI formats it (`src/lib/format.ts`).
 */
export type Progress = {
	/**  0.0 to 1.0. */
	fraction: number,
	action: ProgressAction,
	/**  Downloaded so far; `None` for Verify. */
	doneBytes: number | null,
	/**  The whole download; only Steam knows it. */
	totalBytes: number | null,
	/**  `None` until it's known. */
	secsLeft: number | null,
	/**  Verify: files checked, and how many there are. */
	doneFiles: number | null,
	totalFiles: number | null,
};

/**  What a job in progress is doing. Steam's are all `Download`; Steam doesn't say which. */
export type ProgressAction = "download" | "install" | "update" | "repair" | "verify";

/**  Where Settings installs Proton builds from. */
export type ProtonKind = "geProton" | "protonCachyos";

/**  A Proton build found; only Guild's own may be removed. */
export type ProtonView = {
	name: string,
	removable: boolean,
};

/**  The queue for the UI, in order; `active` is the head's key (also while paused). */
export type QueueView = {
	jobs: QueuedView[],
	paused: boolean,
	active: string | null,
};

export type QueuedAction = "install" | "update" | "verify";

/**  One queued job as `poll` reports it. */
export type QueuedView = {
	key: string,
	action: QueuedAction,
	title: string,
};

/**  A release Settings can install: its tag, the build's name and whether that build is installed. */
export type ReleaseView = {
	tag: string,
	name: string,
	installed: boolean,
};

/**
 *  Windows games on Linux, for Settings: whether umu-launcher and winetricks are found, the Proton builds found
 *  (newest first) and the one chosen in Settings (none is the newest).
 */
export type RunnerView = {
	umu: boolean,
	protons: ProtonView[],
	proton: string | null,
	winetricks: boolean,
};

export type SavesView = {
	/**  The game's own choice; `None` follows the setting. */
	choice: boolean | null,
	/**  Unix seconds of the last sync that worked; `None` when never synced or `error` is set. */
	syncedAt: number | null,
	/**  What went wrong with the last sync; the Overview repeats it. */
	error: Msg | null,
};

/**  A run of `count` cards in `Library::games`; `group` is its id (`view::group`), which the UI names. */
export type Section = {
	group: string,
	count: number,
};

export type SettingsView = {
	/**  The Language setting as saved: "system", "en" or "nl". */
	language: string,
	/**  The language the UI shows (`msg::language`). */
	uiLanguage: string,
	/**  Whether Steam is installed on this PC. */
	steam: boolean,
	steamLibrary: SteamLibrary,
	epic: StoreLogin | null,
	/**  The logged-in Epic account's display name, when Legendary's session file has one. */
	epicAccount: string | null,
	epicInstallDir: string | null,
	gog: StoreLogin | null,
	/**  The logged-in GOG account's name, once a GOG scan has fetched it. */
	gogAccount: string | null,
	gogInstallDir: string | null,
	amazon: StoreLogin | null,
	/**  The logged-in Amazon account's first name, from Nile's file. */
	amazonAccount: string | null,
	amazonInstallDir: string | null,
	/**
	 *  Where Epic, GOG and Amazon install without an install folder setting: `%USERPROFILE%\Games`, Legendary's
	 *  default and the one Guild passes to gogdl and Nile.
	 */
	defaultInstallDir: string | null,
	igdbClientId: string | null,
	/**  Whether a secret is saved; its value never leaves Credential Manager. */
	igdbSecretSet: boolean,
	/**  Whether a SteamGridDB API key is saved; like the secret, it never leaves Credential Manager. */
	steamgriddbKeySet: boolean,
	showBanner: boolean,
	ambient: boolean,
	cloudSaves: boolean,
	gogCloudSaves: boolean,
	/**  Read from the autostart entry itself, so it can't drift from what Windows runs. */
	startWithWindows: boolean,
	/**  Picks the Linux wording where the Windows one names Windows. */
	linux: boolean,
	closeToTray: boolean,
	notifyDownloads: boolean,
	appVersion: string,
	tools: ToolView[],
	/**  Linux: what Windows games run with; `None` on Windows. */
	runner: RunnerView | null,
	cacheBytes: number,
};

export type Sort = "title" | "lastPlayed" | 
/**  Was `playtime`; the old name still parses. */
"mostPlayed" | 
/**  Was `playtime`; the old name still parses. */
"playtime" | "longestToBeat" | "shortestToBeat";

export type SteamDlc = {
	id: string,
	title: string,
};

/**  The owned-games login, separate from the local install. */
export type SteamLibrary = {
	/**  The connected account; `None` when not connected. */
	account: string | null,
	/**  Steam rejected the saved login; connect again. */
	attention: boolean,
};

export type Store = "steam" | "epic" | "gog" | "amazon" | 
/**  A program the owner added (`custom_games`); never merged with a store copy. */
"custom";

/**  An Epic, GOG or Amazon login as its tool (Legendary, gogdl, Nile) reports it. */
export type StoreLogin = 
/**  The tool's exe is in none of the places `tools::Tool::exe` looks. */
"noTool" | "loggedOut" | "loggedIn" | 
/**  The tool couldn't confirm the login, e.g. offline: keep the last known games. */
"unreachable";

/**  Seconds; `None` when unknown. */
export type TimeToBeat = {
	normally: number | null,
	hastily: number | null,
	completely: number | null,
};

export type ToolView = {
	name: string,
	/**  `--version` worked, wherever the tool was found. */
	installed: boolean,
	version: string | null,
	/**  Found in our tools folder. */
	managed: boolean,
	pinned: string,
	/**  Ours, and not the pinned version. */
	update: boolean,
};

export type UpdateInfo = {
	version: string,
	/**  The release notes, Markdown from CHANGELOG.md. */
	notes: string,
};

/**
 *  The toolbar's sort as last saved, the version this start updated to (`settings::take_updated`), and the UI's
 *  language (`msg::language`).
 */
export type ViewPrefs = {
	sort: Sort,
	updatedTo: string | null,
	uiLanguage: string,
};

